package theme

import (
	"image/color"
	"math"
)

// Default colors.
//
// Theme.Color falls back to Monaco 0.56's color registry: colors_gen.go
// (generated by ui/editor/langs/gen/export_colors.mjs) holds every
// registered id's default value per base theme type, as Monaco's
// registerColor declares it (a color, a reference to another id, or a
// transform such as transparent(editor.selectionBackground, 0.3)), and the
// final colors those defaults give under the four base themes. A theme
// whose colors are its base theme's uses the final colors; any other theme
// resolves the defaults against its own colors, as Monaco's
// StandaloneTheme.getColor does, so a custom editor.background also
// becomes the default editorGutter.background.
//
// The color arithmetic follows Monaco's Color class (vs/base/common/
// color.js): RGBA channels are integers and alpha a number rounded to three
// decimals; lighten and darken go through HSLA, whose saturation and
// lightness are rounded to three decimals too, and a color made from HSLA
// keeps it for the next lighten or darken. Copyright (c) Microsoft
// Corporation, MIT License (see NOTICE).

// colorOp is the kind of a colorValue (Monaco's ColorTransformType, plus
// literals and references).
type colorOp uint8

const (
	opLit colorOp = iota
	opRef
	opDarken
	opLighten
	opTransparent
	opOpaque
	opOneOf
	opLessProminent
	opIfDefined
	opMix
)

// colorValue is a registry default (Monaco's ColorValue). nil is a null
// default: no color.
type colorValue struct {
	op     colorOp
	lit    mcolor
	ref    string // opRef, opIfDefined (the id tested)
	args   []*colorValue
	f1, f2 float64
}

func cLit(r, g, b uint8, a float64) *colorValue {
	return &colorValue{op: opLit, lit: rgbaColor(float64(r), float64(g), float64(b), a)}
}
func cRef(id string) *colorValue { return &colorValue{op: opRef, ref: id} }
func cDarken(v *colorValue, f float64) *colorValue {
	return &colorValue{op: opDarken, args: []*colorValue{v}, f1: f}
}
func cLighten(v *colorValue, f float64) *colorValue {
	return &colorValue{op: opLighten, args: []*colorValue{v}, f1: f}
}
func cTransparent(v *colorValue, f float64) *colorValue {
	return &colorValue{op: opTransparent, args: []*colorValue{v}, f1: f}
}
func cOpaque(v, bg *colorValue) *colorValue {
	return &colorValue{op: opOpaque, args: []*colorValue{v, bg}}
}
func cOneOf(vs ...*colorValue) *colorValue { return &colorValue{op: opOneOf, args: vs} }
func cLessProminent(v, bg *colorValue, factor, transparency float64) *colorValue {
	return &colorValue{op: opLessProminent, args: []*colorValue{v, bg}, f1: factor, f2: transparency}
}
func cIfDefined(id string, then, els *colorValue) *colorValue {
	return &colorValue{op: opIfDefined, ref: id, args: []*colorValue{then, els}}
}
func cMix(a, b *colorValue, ratio float64) *colorValue {
	return &colorValue{op: opMix, args: []*colorValue{a, b}, f1: ratio}
}

// mcolor is a color as Monaco's Color holds it.
type mcolor struct {
	r, g, b int
	a       float64
	hsl     *hsla // the HSLA it was made from, nil when made from RGBA
}

type hsla struct{ h, s, l, a float64 }

// jsRound is JavaScript's Math.round (halves round up).
func jsRound(x float64) float64 { return math.Floor(x + 0.5) }

func roundFloat(x float64, decimals int) float64 {
	p := math.Pow(10, float64(decimals))
	return jsRound(x*p) / p
}

func clamp(x, lo, hi float64) float64 { return math.Max(lo, math.Min(hi, x)) }

// rgbaColor is Monaco's new Color(new RGBA(r, g, b, a)).
func rgbaColor(r, g, b, a float64) mcolor {
	ch := func(v float64) int { return int(math.Trunc(clamp(v, 0, 255))) } // Math.min/max then | 0
	return mcolor{r: ch(r), g: ch(g), b: ch(b), a: roundFloat(clamp(a, 0, 1), 3)}
}

// hslaColor is Monaco's new Color(new HSLA(h, s, l, a)).
func hslaColor(h, s, l, a float64) mcolor {
	hs := &hsla{
		h: math.Trunc(clamp(h, 0, 360)),
		s: roundFloat(clamp(s, 0, 1), 3),
		l: roundFloat(clamp(l, 0, 1), 3),
		a: roundFloat(clamp(a, 0, 1), 3),
	}
	c := hslToRGBA(hs)
	c.hsl = hs
	return c
}

// hslaOf is Monaco's Color.hsla.
func (c mcolor) hslaOf() hsla {
	if c.hsl != nil {
		return *c.hsl
	}
	r, g, b := float64(c.r)/255, float64(c.g)/255, float64(c.b)/255
	mx, mn := math.Max(r, math.Max(g, b)), math.Min(r, math.Min(g, b))
	h, s := 0.0, 0.0
	l := (mn + mx) / 2
	if chroma := mx - mn; chroma > 0 {
		if l <= 0.5 {
			s = math.Min(chroma/(2*l), 1)
		} else {
			s = math.Min(chroma/(2-2*l), 1)
		}
		switch mx {
		case r:
			h = (g - b) / chroma
			if g < b {
				h += 6
			}
		case g:
			h = (b-r)/chroma + 2
		case b:
			h = (r-g)/chroma + 4
		}
		h = jsRound(h * 60)
	}
	return hsla{
		h: math.Trunc(clamp(h, 0, 360)),
		s: roundFloat(clamp(s, 0, 1), 3),
		l: roundFloat(clamp(l, 0, 1), 3),
		a: roundFloat(clamp(c.a, 0, 1), 3),
	}
}

func hue2rgb(p, q, t float64) float64 {
	if t < 0 {
		t++
	}
	if t > 1 {
		t--
	}
	switch {
	case t < 1.0/6:
		return p + (q-p)*6*t
	case t < 1.0/2:
		return q
	case t < 2.0/3:
		return p + (q-p)*(2.0/3-t)*6
	}
	return p
}

func hslToRGBA(hs *hsla) mcolor {
	h := hs.h / 360
	var r, g, b float64
	if hs.s == 0 {
		r, g, b = hs.l, hs.l, hs.l
	} else {
		q := hs.l + hs.s - hs.l*hs.s
		if hs.l < 0.5 {
			q = hs.l * (1 + hs.s)
		}
		p := 2*hs.l - q
		r, g, b = hue2rgb(p, q, h+1.0/3), hue2rgb(p, q, h), hue2rgb(p, q, h-1.0/3)
	}
	return rgbaColor(jsRound(r*255), jsRound(g*255), jsRound(b*255), hs.a)
}

func (c mcolor) lighten(f float64) mcolor {
	h := c.hslaOf()
	return hslaColor(h.h, h.s, h.l+h.l*f, h.a)
}

func (c mcolor) darken(f float64) mcolor {
	h := c.hslaOf()
	return hslaColor(h.h, h.s, h.l-h.l*f, h.a)
}

func (c mcolor) transparent(f float64) mcolor {
	return rgbaColor(float64(c.r), float64(c.g), float64(c.b), c.a*f)
}

func (c mcolor) makeOpaque(bg mcolor) mcolor {
	if c.a == 1 || bg.a != 1 {
		return c
	}
	mixc := func(o, v int) float64 { return float64(o) - c.a*float64(o-v) }
	return rgbaColor(mixc(bg.r, c.r), mixc(bg.g, c.g), mixc(bg.b, c.b), 1)
}

func (c mcolor) mix(o mcolor, factor float64) mcolor {
	n := clamp(factor, 0, 1)
	m := func(a, b float64) float64 { return a + (b-a)*n }
	return rgbaColor(m(float64(c.r), float64(o.r)), m(float64(c.g), float64(o.g)), m(float64(c.b), float64(o.b)), m(c.a, o.a))
}

func relLum(v int) float64 {
	c := float64(v) / 255
	if c <= 0.03928 {
		return c / 12.92
	}
	return math.Pow((c+0.055)/1.055, 2.4)
}

func (c mcolor) luminance() float64 {
	return roundFloat(0.2126*relLum(c.r)+0.7152*relLum(c.g)+0.0722*relLum(c.b), 4)
}

func lighterColor(of, rel mcolor, factor float64) mcolor {
	if of.luminance() > rel.luminance() {
		return of
	}
	if factor == 0 {
		factor = 0.5
	}
	l1, l2 := of.luminance(), rel.luminance()
	return of.lighten(factor * (l2 - l1) / l2)
}

func darkerColor(of, rel mcolor, factor float64) mcolor {
	if of.luminance() < rel.luminance() {
		return of
	}
	if factor == 0 {
		factor = 0.5
	}
	l1, l2 := of.luminance(), rel.luminance()
	return of.darken(factor * (l1 - l2) / l1)
}

func (c mcolor) nrgba() color.NRGBA {
	return color.NRGBA{uint8(c.r), uint8(c.g), uint8(c.b), uint8(jsRound(c.a * 255))}
}

// fromNRGBA is Color.fromHex of a theme's own color.
func fromNRGBA(c color.NRGBA) mcolor {
	return rgbaColor(float64(c.R), float64(c.G), float64(c.B), float64(c.A)/255)
}

// baseType is the column of the default tables for a base theme name.
func baseType(base string) int {
	switch base {
	case "vs-dark":
		return 1
	case "hc-black":
		return 2
	case "hc-light":
		return 3
	}
	return 0
}

// resolver resolves registry defaults against one theme's own colors
// (Monaco's StandaloneTheme.getColor / getDefault).
type resolver struct {
	t     *Theme
	typ   int
	memo  map[string]*mcolor
	depth int
}

func (r *resolver) color(id string) *mcolor {
	if c, ok := r.t.colors[id]; ok {
		m := fromNRGBA(c)
		return &m
	}
	if c, ok := r.memo[id]; ok {
		return c
	}
	var c *mcolor
	if d, ok := colorDefaults[id]; ok && r.depth < 64 {
		r.depth++
		c = r.value(d[r.typ])
		r.depth--
	}
	r.memo[id] = c
	return c
}

func (r *resolver) value(v *colorValue) *mcolor {
	if v == nil {
		return nil
	}
	arg := func(i int) *mcolor { return r.value(v.args[i]) }
	apply := func(f func(mcolor) mcolor) *mcolor {
		if c := arg(0); c != nil {
			x := f(*c)
			return &x
		}
		return nil
	}
	switch v.op {
	case opLit:
		c := v.lit
		return &c
	case opRef:
		return r.color(v.ref)
	case opDarken:
		return apply(func(c mcolor) mcolor { return c.darken(v.f1) })
	case opLighten:
		return apply(func(c mcolor) mcolor { return c.lighten(v.f1) })
	case opTransparent:
		return apply(func(c mcolor) mcolor { return c.transparent(v.f1) })
	case opOpaque:
		bg := arg(1)
		if bg == nil {
			return arg(0)
		}
		return apply(func(c mcolor) mcolor { return c.makeOpaque(*bg) })
	case opOneOf:
		for i := range v.args {
			if c := arg(i); c != nil {
				return c
			}
		}
		return nil
	case opLessProminent:
		from := arg(0)
		if from == nil {
			return nil
		}
		bg := arg(1)
		var x mcolor
		switch {
		case bg == nil:
			x = from.transparent(v.f1 * v.f2)
		case from.luminance() < bg.luminance():
			x = lighterColor(*from, *bg, v.f1).transparent(v.f2)
		default:
			x = darkerColor(*from, *bg, v.f1).transparent(v.f2)
		}
		return &x
	case opIfDefined:
		if _, ok := r.t.colors[v.ref]; ok {
			return arg(0)
		}
		return arg(1)
	case opMix:
		a, b := arg(0), arg(1)
		if a == nil {
			t := rgbaColor(0, 0, 0, 0)
			a = &t
		}
		if b == nil {
			t := rgbaColor(0, 0, 0, 0)
			b = &t
		}
		x := a.mix(*b, v.f1)
		return &x
	}
	return nil
}

// resolveDefault resolves id's registry default against t's own colors.
func resolveDefault(t *Theme, id string) (color.NRGBA, bool) {
	r := &resolver{t: t, typ: baseType(t.base), memo: map[string]*mcolor{}}
	if c := r.color(id); c != nil {
		return c.nrgba(), true
	}
	return color.NRGBA{}, false
}

// defaultColor returns id's final color under base theme type typ from
// the generated table.
func defaultColor(id string, typ int) (color.NRGBA, bool) {
	row, ok := defaultColors[id]
	if !ok || defaultUnset[id]&(1<<typ) != 0 {
		return color.NRGBA{}, false
	}
	return row[typ], true
}
